    fun resolve(value: String?): SettingsSearchEntry? = value?.let { key ->
        entries.firstOrNull { it.id == key || it.title.equals(key, true) || it.aliases.any { alias -> alias.equals(key, true) } }
    }
    fun id(value: String?): String? = resolve(value)?.id ?: value
    fun routeFor(value: String): String = resolve(value)?.route ?: "preferences_hub"
